#!/usr/bin/env python3
"""Generate / refresh navigation headers in task-level playbooks (B-layer).

Each task playbook gets a marked block right below its H1:

    <!-- nav:start (generated by scripts/gen_nav_headers.py; do not edit by hand) -->
    > **Sections**: Ask First · Workflow · Defaults · Rules & Pitfalls · Pre-Delivery Checks · Scope Boundaries
    > **Must not skip**: Defaults · Pre-Delivery Checks · Scope Boundaries — return here before delivery.
    > **Formats**: excel_standards.md · metric_disambiguation.md
    <!-- nav:end -->

Data sources (single source of truth, no parallel facts):
  - Sections line   : the file's own `## ` headings (scanned live).
  - Must-not-skip   : the intersection of the file's headings with
                      MUST_NOT_SKIP_CANONICAL (delivery-gate sections).
  - Formats line    : task-catalog.json `formats` -> format_registry paths.

validate_skill.py re-derives the same block and fails when a file's nav header
is stale, so headings and nav can never drift apart.

Usage:
  python3 scripts/gen_nav_headers.py           # rewrite stale headers
  python3 scripts/gen_nav_headers.py --check   # exit 1 if any header is stale
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PLAYBOOKS = ROOT / "references" / "corporate-finance" / "playbooks"
TASK_CATALOG = ROOT / "references" / "corporate-finance" / "task-catalog.json"

NAV_START = "<!-- nav:start (generated by scripts/gen_nav_headers.py; do not edit by hand) -->"
NAV_END = "<!-- nav:end -->"
NAV_BLOCK = re.compile(
    re.escape(NAV_START) + r".*?" + re.escape(NAV_END) + r"\n?", re.DOTALL
)

# Delivery-gate sections: if present in a playbook, the agent must return to
# them before delivering. Order here defines display order.
MUST_NOT_SKIP_CANONICAL = (
    "Defaults",
    "Rules & Pitfalls",
    "Pre-Delivery Checks",
    "Scope Boundaries",
    "Quality Gate",
    "Interface",
)

# Sections that are informative but not delivery gates (shown in Sections line only).
H2 = re.compile(r"^## (.+?)\s*$", re.MULTILINE)


def load_catalog() -> tuple[dict[str, dict], dict[str, str]]:
    catalog = json.loads(TASK_CATALOG.read_text(encoding="utf-8"))
    by_playbook = {task["playbook"]: task for task in catalog["tasks"]}
    registry = {
        name: spec["path"] if isinstance(spec, dict) else spec
        for name, spec in catalog.get("format_registry", {}).items()
    }
    return by_playbook, registry


def build_nav(text: str, task: dict | None, registry: dict[str, str]) -> str:
    headings = H2.findall(NAV_BLOCK.sub("", text))
    sections = " · ".join(headings) if headings else "(no sections)"
    gates = [h for h in MUST_NOT_SKIP_CANONICAL if h in headings]
    lines = [NAV_START, f"> **Sections**: {sections}"]
    if gates:
        lines.append(
            f"> **Must not skip**: {' · '.join(gates)} — return here before delivery."
        )
    if task and task.get("formats"):
        fmt_names = [Path(registry.get(f, f)).name for f in task["formats"]]
        lines.append(f"> **Formats**: {' · '.join(fmt_names)}")
    lines.append(NAV_END)
    return "\n".join(lines)


def apply(path: Path, by_playbook: dict[str, dict], registry: dict[str, str]) -> tuple[bool, bool]:
    """Returns (changed, stale_before)."""
    rel = str(path.relative_to(ROOT))
    text = path.read_text(encoding="utf-8")
    task = by_playbook.get(rel)
    nav = build_nav(text, task, registry)

    if NAV_BLOCK.search(text):
        new_text = NAV_BLOCK.sub(nav + "\n", text, count=1)
        stale = new_text != text
        if stale:
            path.write_text(new_text, encoding="utf-8")
        return stale, stale

    # insert below H1 (first line starting with "# ")
    lines = text.splitlines(keepends=False)
    h1_idx = next((i for i, l in enumerate(lines) if l.startswith("# ")), None)
    if h1_idx is None:
        return False, False
    insert_at = h1_idx + 1
    # skip a single blank line after H1 to keep spacing tidy
    block = ["", nav]
    lines[insert_at:insert_at] = block
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return True, True


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if any nav header is stale")
    args = parser.parse_args()

    by_playbook, registry = load_catalog()
    stale_files: list[str] = []
    for path in sorted(PLAYBOOKS.rglob("*.md")):
        if path.name == "_overview.md":
            continue
        if args.check:
            rel = str(path.relative_to(ROOT))
            text = path.read_text(encoding="utf-8")
            nav = build_nav(text, by_playbook.get(rel), registry)
            current = NAV_BLOCK.search(text)
            if not current or current.group(0).rstrip("\n") != nav:
                stale_files.append(rel)
        else:
            changed, _ = apply(path, by_playbook, registry)
            if changed:
                print(f"nav updated: {path.relative_to(ROOT)}")

    if args.check:
        if stale_files:
            print("stale nav headers (run scripts/gen_nav_headers.py):")
            for rel in stale_files:
                print(f"  - {rel}")
            return 1
        print("all nav headers up to date")
    return 0


if __name__ == "__main__":
    sys.exit(main())
